from typing import Dict

def store_info_in_header(
    info_type: str, 
    info_content: str, 
    header: Dict[str, str]
) -> Dict[str, str]:
    type_mapping = {
        'lang': 'Accept-Language',
        'encoding': 'Accept-Encoding',
        'cache': 'Cache-Control'
    }

    if info_type not in type_mapping:
        return header

    if not isinstance(info_content, str):
        return header

    sanitized = info_content.strip()
    if not sanitized:
        return header

    max_length = 1024
    if len(sanitized) > max_length:
        return header

    updated = header.copy()
    updated[type_mapping[info_type]] = sanitized
    return updated
